function validDate(value:string|null,fallback:string){return value&&/^\d{4}-\d{2}-\d{2}$/.test(value)?value:fallback}
async function accountabilityReports(request:Request,env:Env,context:SessionContext){
 if(!allowed(context,'bakery.reconciliation'))return json({error:'Bakery Reconciliation View permission is required.'},403);
 const reportAccess={flour:allowed(context,'bakery.flour_control'),bread:allowed(context,'bakery.report.bread_accountability'),returns:allowed(context,'bakery.report.returns'),cash:allowed(context,'bakery.report.cash_collection'),pos:allowed(context,'bakery.report.pos_charges'),debt:allowed(context,'bakery.report.outstanding_debt'),theft:allowed(context,'bakery.report.theft_investigation')};
 const url=new URL(request.url);if(url.searchParams.get('section')==='flour'&&!reportAccess.flour)return json({error:'Report not found.'},404);const today=businessDate(),defaultFrom=new Date(`${today}T00:00:00Z`);defaultFrom.setUTCDate(defaultFrom.getUTCDate()-29);const dateFrom=validDate(url.searchParams.get('dateFrom'),defaultFrom.toISOString().slice(0,10)),dateTo=validDate(url.searchParams.get('dateTo'),today);if(dateFrom>dateTo)return json({error:'Report start date must not be after end date.'},400);const span=(new Date(`${dateTo}T00:00:00Z`).getTime()-new Date(`${dateFrom}T00:00:00Z`).getTime())/86400000;if(span>366)return json({error:'Accountability report range cannot exceed 366 days.'},400);
 const[bread,money,custodians,flour,exceptions]=await Promise.all([
  env.DB.prepare(`SELECT bl.business_date AS businessDate,bl.status,bp.id AS productId,bp.name AS productName,d.id AS dispatchId,d.dispatch_no AS dispatchNo,c.id AS custodianId,c.name AS custodianName,COALESCE(SUM(bl.quantity),0) AS quantity FROM bakery_bread_ledger bl JOIN bakery_products bp ON bp.id=bl.product_id LEFT JOIN bakery_dispatches d ON d.id=bl.dispatch_id LEFT JOIN bakery_custodians c ON c.id=bl.custodian_id WHERE bl.company_id=? AND bl.business_date BETWEEN ? AND ? GROUP BY bl.business_date,bl.status,bp.id,d.id,c.id ORDER BY bl.business_date DESC,bl.status,bp.name LIMIT 2000`).bind(COMPANY,dateFrom,dateTo).all<Record<string,unknown>>(),
  env.DB.prepare(`SELECT ml.business_date AS businessDate,ml.status,d.id AS dispatchId,d.dispatch_no AS dispatchNo,c.id AS custodianId,c.name AS custodianName,ml.reference,COALESCE(SUM(ml.amount_kobo),0) AS amountKobo FROM bakery_money_ledger ml LEFT JOIN bakery_dispatches d ON d.id=ml.dispatch_id LEFT JOIN bakery_custodians c ON c.id=ml.custodian_id WHERE ml.company_id=? AND ml.business_date BETWEEN ? AND ? GROUP BY ml.business_date,ml.status,d.id,c.id,ml.reference ORDER BY ml.business_date DESC,ml.status LIMIT 2000`).bind(COMPANY,dateFrom,dateTo).all<Record<string,unknown>>(),
  env.DB.prepare(`SELECT c.id,c.name,c.custodian_type AS custodianType,COUNT(DISTINCT d.id) AS dispatchCount,COALESCE(SUM(di.quantity),0) AS dispatchedQty,COALESCE((SELECT SUM(bl.quantity) FROM bakery_bread_ledger bl JOIN bakery_dispatches x ON x.id=bl.dispatch_id WHERE x.custodian_id=c.id AND bl.business_date BETWEEN ? AND ? AND bl.status='sold'),0) AS soldQty,COALESCE((SELECT SUM(ml.amount_kobo) FROM bakery_money_ledger ml JOIN bakery_dispatches x ON x.id=ml.dispatch_id WHERE x.custodian_id=c.id AND ml.business_date BETWEEN ? AND ? AND ml.status IN ('cash_received','pos_received','transfer_received')),0) AS remittedKobo,COALESCE((SELECT SUM(ml.amount_kobo) FROM bakery_money_ledger ml JOIN bakery_dispatches x ON x.id=ml.dispatch_id WHERE x.custodian_id=c.id AND ml.business_date BETWEEN ? AND ? AND ml.status='outstanding'),0) AS outstandingKobo FROM bakery_custodians c LEFT JOIN bakery_dispatches d ON d.custodian_id=c.id AND date(d.created_at) BETWEEN ? AND ? LEFT JOIN bakery_dispatch_items di ON di.dispatch_id=d.id WHERE c.company_id=? GROUP BY c.id ORDER BY remittedKobo DESC,c.name LIMIT 300`).bind(dateFrom,dateTo,dateFrom,dateTo,dateFrom,dateTo,dateFrom,dateTo,COMPANY).all<Record<string,unknown>>(),
  reportAccess.flour?env.DB.prepare(`SELECT i.id AS inventoryItemId,i.sku,i.name,i.unit,COALESCE(f.bag_weight_kg,50) AS bagWeightKg,COALESCE(SUM(bri.planned_quantity),0) AS plannedQuantity,COALESCE(SUM(bri.actual_quantity),0) AS usedQuantity,COALESCE(SUM(bri.waste_quantity),0) AS wasteQuantity,COALESCE(SUM((bri.actual_quantity+bri.waste_quantity)*bri.unit_cost_kobo),0) AS usageCostKobo,COUNT(DISTINCT bri.batch_id) AS batchCount FROM bakery_batch_ingredients bri JOIN bakery_batches b ON b.id=bri.batch_id JOIN inventory_items i ON i.id=bri.inventory_item_id LEFT JOIN bakery_flour_bag_settings f ON f.inventory_item_id=i.id AND f.company_id=b.company_id AND f.active=1 WHERE b.company_id=? AND date(bri.issued_at) BETWEEN ? AND ? AND (lower(i.name) LIKE '%flour%' OR lower(i.sku) LIKE '%flour%') GROUP BY i.id ORDER BY usedQuantity DESC LIMIT 100`).bind(COMPANY,dateFrom,dateTo).all<Record<string,unknown>>() : Promise.resolve({results:[] as Record<string,unknown>[]}),
  env.DB.prepare(`SELECT exception_type AS exceptionType,severity,status,COUNT(*) AS count,COALESCE(SUM(ABS(quantity_variance)),0) AS quantityVariance,COALESCE(SUM(ABS(amount_variance_kobo)),0) AS amountVarianceKobo FROM bakery_accountability_exceptions WHERE company_id=? AND business_date BETWEEN ? AND ? GROUP BY exception_type,severity,status ORDER BY severity,exception_type`).bind(COMPANY,dateFrom,dateTo).all<Record<string,unknown>>(),
 ]);
 const flourUsage=(flour.results||[]).map(row=>{const bagWeightKg=Math.max(.001,Number(row.bagWeightKg||50)),used=Number(row.usedQuantity||0),waste=Number(row.wasteQuantity||0);return{...row,bagWeightKg,usedBags:used/bagWeightKg,wasteBags:waste/bagWeightKg,varianceQuantity:used+waste-Number(row.plannedQuantity||0),wastePercent:used+waste>0?waste/(used+waste)*100:0}});
 const breadRows=(bread.results||[]).filter(row=>reportAccess.bread||(reportAccess.returns&&row.status==='returned')),moneyStatuses=[...(reportAccess.cash?['cash_received','pos_received','transfer_received']:[]),...(reportAccess.pos?['pos_charges']:[]),...(reportAccess.debt?['outstanding']:[])],moneyRows=(money.results||[]).filter(row=>moneyStatuses.includes(String(row.status))),todayMs=new Date(`${today}T00:00:00Z`).getTime(),debtAgeing={current:0,days31to60:0,days61to90:0,over90:0};for(const row of moneyRows){if(row.status!=='outstanding')continue;const age=Math.max(0,Math.floor((todayMs-new Date(`${row.businessDate}T00:00:00Z`).getTime())/86400000)),amount=Number(row.amountKobo||0);if(age<=30)debtAgeing.current+=amount;else if(age<=60)debtAgeing.days31to60+=amount;else if(age<=90)debtAgeing.days61to90+=amount;else debtAgeing.over90+=amount}
 return json({dateFrom,dateTo,generatedAt:new Date().toISOString(),capabilities:reportAccess,debtAgeing,descriptions:{breadAccountability:'Shows where every loaf moved during the selected period.',moneyAccountability:'Shows how every naira was classified as received, outstanding, refunded or charged.',custodianPerformance:'Compares bread issued, bread sold, collections and outstanding balances for each agent or reseller.',...(reportAccess.flour?{flourUsage:'Compares planned flour with actual flour used and wasted in completed production batches.'}:{}),investigation:'Summarizes possible theft, missing bread and unremitted-sales exceptions.'},breadAccountability:breadRows,moneyAccountability:moneyRows,custodianPerformance:custodians.results||[],...(reportAccess.flour?{flourUsage}:{}),investigation:reportAccess.theft?exceptions.results||[]:[]});
}

