const csvCell=(value:unknown)=>`"${String(value??'').replaceAll('"','""')}"`;
async function exportReport(request:Request,env:Env,context:SessionContext){const section=new URL(request.url).searchParams.get('section')||'custodians';if(section==='flour'&&!allowed(context,'bakery.flour_control'))return json({error:'Report not found.'},404);const reportResponse=await accountabilityReports(request,env,context);if(!reportResponse.ok)return reportResponse;const report=await reportResponse.json() as Record<string,unknown>,capabilities=(report.capabilities||{}) as Record<string,boolean>;let headers:string[]=[],rows:unknown[][]=[];if(section==='flour'){if(!capabilities.flour)return json({error:'Report not found.'},404);headers=['Item','SKU','Unit','Bag weight kg','Planned','Used','Used bags','Waste','Waste bags','Variance','Waste percent','Usage cost kobo'];rows=((report.flourUsage||[]) as Array<Record<string,unknown>>).map(r=>[r.name,r.sku,r.unit,r.bagWeightKg,r.plannedQuantity,r.usedQuantity,r.usedBags,r.wasteQuantity,r.wasteBags,r.varianceQuantity,r.wastePercent,r.usageCostKobo])}else if(['bread','returns'].includes(section)){if(!capabilities[section])return json({error:`${section==='bread'?'Bread Accountability':'Returns'} Report permission is required.`},403);headers=['Date','Status','Product','Dispatch','Custodian','Quantity'];rows=((report.breadAccountability||[]) as Array<Record<string,unknown>>).filter(r=>section==='bread'||r.status==='returned').map(r=>[r.businessDate,r.status,r.productName,r.dispatchNo,r.custodianName,r.quantity])}else if(['cash','pos','debt'].includes(section)){if(!capabilities[section])return json({error:`${section==='cash'?'Cash Collection':section==='pos'?'POS Charges':'Outstanding Debt'} Report permission is required.`},403);const statuses=section==='cash'?['cash_received','pos_received','transfer_received']:section==='pos'?['pos_charges']:['outstanding'];headers=['Date','Status','Dispatch','Custodian','Reference','Amount kobo'];rows=((report.moneyAccountability||[]) as Array<Record<string,unknown>>).filter(r=>statuses.includes(String(r.status))).map(r=>[r.businessDate,r.status,r.dispatchNo,r.custodianName,r.reference,r.amountKobo])}else if(section==='theft'){if(!capabilities.theft)return json({error:`Theft Investigation Report permission is required.`},403);headers=['Exception type','Severity','Status','Cases','Bread variance','Money variance kobo'];rows=((report.investigation||[]) as Array<Record<string,unknown>>).map(r=>[r.exceptionType,r.severity,r.status,r.count,r.quantityVariance,r.amountVarianceKobo])}else{headers=['Custodian','Type','Dispatches','Dispatched','Sold','Remitted kobo','Outstanding kobo'];rows=((report.custodianPerformance||[]) as Array<Record<string,unknown>>).map(r=>[r.name,r.custodianType,r.dispatchCount,r.dispatchedQty,r.soldQty,r.remittedKobo,r.outstandingKobo])}const csv=[headers,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n');try{await env.DB.prepare(`INSERT INTO audit_logs(id,actor_employee_id,company_id,module,action,entity_type,entity_id,after_json,source,request_id) VALUES(?,?,?,'bakery','export_report','bakery_accountability_report',?,?,'web',?)`).bind(uid('audit'),context.employee.id,COMPANY,uid('bakery-report-export'),JSON.stringify({format:'csv',section,dateFrom:report.dateFrom,dateTo:report.dateTo,rowCount:rows.length}),requestCorrelationId(request)).run()}catch{return json({error:'The report is temporarily unavailable.'},503)}return new Response(csv,{headers:{'content-type':'text/csv; charset=utf-8','content-disposition':`attachment; filename="bakery-${section}-${businessDate()}.csv"`,'cache-control':'no-store'}})}

export async function routeBakeryAccountability(request:Request,env:Env,context:SessionContext):Promise<Response|null>{const url=new URL(request.url),evidenceMatch=url.pathname.match(/^\/api\/bakery\/accountability\/investigations\/evidence\/([^/]+)$/);if(evidenceMatch&&['GET','HEAD'].includes(request.method))return streamInvestigationEvidence(request,env,context,decodeURIComponent(evidenceMatch[1]));if(url.pathname==='/api/bakery/accountability/investigations/evidence'&&request.method==='GET')return listInvestigationEvidence(request,env,context);if(url.pathname==='/api/bakery/accountability/investigations/evidence'&&request.method==='POST')return uploadInvestigationEvidence(request,env,context);if(url.pathname==='/api/bakery/accountability'&&request.method==='GET')return overview(env,context);if(url.pathname==='/api/bakery/accountability/reports'&&request.method==='GET')return accountabilityReports(request,env,context);if(url.pathname==='/api/bakery/accountability/reports/export'&&request.method==='GET')return exportReport(request,env,context);if(url.pathname==='/api/bakery/accountability/flour-bag'&&request.method==='POST')return saveFlourBag(request,env,context);if(url.pathname==='/api/bakery/accountability/investigations'&&request.method==='POST')return investigationAction(request,env,context);if(url.pathname==='/api/bakery/accountability/custodians'&&request.method==='POST')return createCustodian(request,env,context);if(url.pathname==='/api/bakery/accountability/dispatches'&&request.method==='POST')return createDispatch(request,env,context);if(url.pathname==='/api/bakery/accountability/bread'&&request.method==='POST')return recordBread(request,env,context);if(url.pathname==='/api/bakery/accountability/money'&&request.method==='POST')return recordMoney(request,env,context);if(url.pathname==='/api/bakery/accountability/returns/verify'&&request.method==='POST')return verifyPhysicalReturns(request,env,context);if(url.pathname==='/api/bakery/accountability/close'&&request.method==='POST')return closeDispatch(request,env,context);return null}
